* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #edf0f4;
  color: #171a21;
  font-family: Inter, Arial, sans-serif;
  letter-spacing: 0;
}

.app {
  min-height: 100vh;
  padding: 18px;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1250px;
  margin: 0 auto 16px;
  padding: 12px 16px;
  background: #ffffff;
  border: 1px solid #d9dee7;
  border-radius: 6px;
}

.toolbar div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.toolbar strong {
  font-size: 14px;
}

.toolbar span {
  color: #687180;
  font-size: 12px;
}

.toolbar button {
  border: 0;
  border-radius: 5px;
  padding: 10px 18px;
  background: #1e40af;
  color: #ffffff;
  font-weight: 700;
  cursor: pointer;
}

.empty {
  max-width: 900px;
  margin: 60px auto;
  padding: 60px 20px;
  background: #ffffff;
  border: 1px dashed #b9c1cd;
  color: #687180;
  text-align: center;
}

.page {
  max-width: 1250px;
  min-height: 210mm;
  margin: 0 auto;
  padding: 14mm;
  background: #ffffff;
  border: 1px solid #d9dee7;
}

.document-header {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  padding-bottom: 14px;
  border-bottom: 2px solid #171a21;
}

.company {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.logo {
  width: 70px;
  max-height: 55px;
  object-fit: contain;
}

.company h1,
.document-title h2 {
  margin: 0;
}

.company h1 {
  margin-bottom: 7px;
  font-size: 20px;
}

.company p,
.document-title p {
  margin: 2px 0;
  color: #626b79;
  font-size: 9px;
}

.document-title {
  text-align: right;
}

.document-title h2 {
  margin-top: 3px;
  font-size: 22px;
}

.eyebrow {
  color: #1e40af;
  font-size: 9px;
  font-weight: 800;
}

.status {
  display: inline-block;
  margin-top: 8px;
  padding: 5px 10px;
  border: 1px solid #c8cfda;
  color: #374151;
  font-size: 9px;
  font-weight: 800;
}

.status-posted {
  border-color: #16a34a;
  color: #166534;
}

.status-approved {
  border-color: #2563eb;
  color: #1d4ed8;
}

.status-cancelled {
  border-color: #dc2626;
  color: #991b1b;
}

.record-information {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin-top: 14px;
  background: #d9dee7;
  border: 1px solid #d9dee7;
}

.record-information div {
  min-height: 47px;
  padding: 8px;
  background: #ffffff;
}

.record-information label,
.notes label {
  display: block;
  margin-bottom: 4px;
  color: #687180;
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
}

.record-information strong {
  font-size: 10px;
}

.summary {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin: 14px 0;
}

.summary div {
  padding: 10px;
  border: 1px solid #d9dee7;
}

.summary span {
  display: block;
  margin-bottom: 5px;
  color: #687180;
  font-size: 8px;
  text-transform: uppercase;
}

.summary strong {
  font-size: 17px;
}

.summary .decrease strong,
.decreased {
  color: #b91c1c;
}

.summary .increase strong,
.increased {
  color: #1d4ed8;
}

.items-section h3 {
  margin: 0 0 8px;
  font-size: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

th,
td {
  padding: 6px;
  border: 1px solid #d9dee7;
  font-size: 8px;
  vertical-align: top;
  overflow-wrap: anywhere;
}

th {
  background: #eef1f5;
  font-weight: 800;
  text-align: left;
}

td strong,
td span,
td small {
  display: block;
}

td small {
  margin-top: 3px;
  color: #687180;
  font-size: 7px;
}

.numeric {
  text-align: right;
}

.price {
  font-weight: 800;
}

.notes {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  margin-top: 14px;
}

.notes div {
  padding: 9px;
  border: 1px solid #d9dee7;
}

.notes p {
  margin: 0;
  font-size: 9px;
  white-space: pre-wrap;
}

.approval {
  display: grid;
  grid-template-columns: repeat(3, 1fr) 180px;
  gap: 14px;
  align-items: end;
  margin-top: 24px;
}

.approval span,
.approval strong {
  display: block;
  font-size: 8px;
}

.approval strong {
  margin-top: 4px;
  min-height: 14px;
}

.signature {
  height: 30px;
  border-bottom: 1px solid #171a21;
}

.barcode {
  overflow: hidden;
  text-align: center;
}

.barcode svg {
  width: 100%;
  max-width: 180px;
}

footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-top: 18px;
  padding-top: 7px;
  border-top: 1px solid #d9dee7;
  color: #687180;
  font-size: 7px;
}

@page {
  size: A4 landscape;
  margin: 8mm;
}
@media print {
  body,
  .app {
    margin: 0;
    padding: 0;
    background: #ffffff;
  }
  .no-print {
    display: none !important;
  }
  .page {
    width: 100%;
    max-width: none;
    min-height: auto;
    margin: 0;
    padding: 0;
    border: 0;
  }
  thead {
    display: table-header-group;
  }
  tr,
  .summary,
  .notes,
  .approval {
    break-inside: avoid;
  }
}

