import React from "https://esm.sh/react@18.2.0";
import { createRoot } from "https://esm.sh/react-dom@18.2.0/client";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function text(value, fallback = "-") {
  if (value === undefined || value === null || value === "") {
    return fallback;
  }

  return String(value);
}

function money(value, currency = "EUR") {
  return new Intl.NumberFormat("hr-HR", {
    style: "currency",
    currency: currency || "EUR"
  }).format(Number(value || 0));
}

function number(value) {
  return Number(value || 0).toFixed(2);
}

function date(value) {
  if (!value) return "-";

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) return text(value);

  return parsed.toLocaleDateString("hr-HR");
}

function dateTime(value) {
  if (!value) return "-";

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) return text(value);

  return parsed.toLocaleString("hr-HR");
}

function statusClass(status) {
  return `status status-${String(status || "DRAFT").toLowerCase()}`;
}

function Barcode({ value }) {
  const reference = React.useRef(null);

  React.useEffect(() => {
    if (!reference.current || !value) return;

    try {
      JsBarcode(reference.current, String(value), {
        format: "CODE128",
        displayValue: true,
        fontSize: 11,
        height: 42,
        width: 1.4,
        margin: 0
      });
    } catch (error) {
      console.log("Barcode error:", error);
    }
  }, [value]);

  return <svg ref={reference}></svg>;
}

function App() {
  const model = appsmith.model || {};
  const header = model.header || {};
  const items = Array.isArray(model.items) ? model.items : [];

  const decreasedCount = Number(
    header.decreasedCount ??
    items.filter(item => Number(item.newPrice) < Number(item.oldPrice)).length
  );

  const increasedCount = Number(
    header.increasedCount ??
    items.filter(item => Number(item.newPrice) > Number(item.oldPrice)).length
  );

  const totalDifference = items.reduce(
    (sum, item) =>
      sum + Number(item.newPrice || 0) - Number(item.oldPrice || 0),
    0
  );

  const isPromotion = header.changeType === "PROMOTION";

  if (!header.recordNumber) {
    return (
      <div className="empty">
        Select a price change record to prepare the print preview.
      </div>
    );
  }

  return (
    <div className="app">
      <div className="toolbar no-print">
        <div>
          <strong>Price Change Record</strong>
          <span>{header.recordNumber}</span>
        </div>

        <button onClick={() => window.print()}>
          Print Record
        </button>
      </div>

      <main className="page">
        <header className="document-header">
          <section className="company">
            {header.companyLogoPath && (
              <img
                className="logo"
                src={header.companyLogoPath}
                alt={header.companyName || "Company"}
              />
            )}

            <div>
              <h1>{text(header.companyName, "Axon")}</h1>
              <p>{text(header.companyAddress)}</p>
              <p>
                {text(header.companyPostalCode, "")}{" "}
                {text(header.companyCity, "")}
              </p>
              <p>Tax No: {text(header.companyTaxNumber)}</p>
              <p>{text(header.companyEmail)} · {text(header.companyPhone)}</p>
            </div>
          </section>

          <section className="document-title">
            <span className="eyebrow">PRODUCT PRICING</span>
            <h2>Price Change Record</h2>
            <p>Zapisnik o promjeni cijena</p>
            <div className={statusClass(header.status)}>
              {text(header.status)}
            </div>
          </section>
        </header>

        <section className="record-information">
          <div>
            <label>Record Number</label>
            <strong>{text(header.recordNumber)}</strong>
          </div>

          <div>
            <label>Record Date</label>
            <strong>{date(header.recordDate)}</strong>
          </div>

          <div>
            <label>Effective Date</label>
            <strong>{date(header.effectiveDate)}</strong>
          </div>

          <div>
            <label>Change Type</label>
            <strong>
              {isPromotion ? "Promotion / Discount" : "Permanent Price Change"}
            </strong>
          </div>

          <div>
            <label>Created By</label>
            <strong>{text(header.createdBy)}</strong>
          </div>

          <div>
            <label>Approved By</label>
            <strong>{text(header.approvedBy)}</strong>
          </div>

          <div>
            <label>Posted By</label>
            <strong>{text(header.postedBy)}</strong>
          </div>

          <div>
            <label>Posted At</label>
            <strong>{dateTime(header.postedAt)}</strong>
          </div>
        </section>

        <section className="summary">
          <div>
            <span>Total Products</span>
            <strong>{items.length}</strong>
          </div>

          <div className="decrease">
            <span>Price Decreases</span>
            <strong>{decreasedCount}</strong>
          </div>

          <div className="increase">
            <span>Price Increases</span>
            <strong>{increasedCount}</strong>
          </div>

          <div>
            <span>Total Price Difference</span>
            <strong>{money(totalDifference)}</strong>
          </div>
        </section>

        <section className="items-section">
          <h3>Price Change Items</h3>

          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Product</th>
                <th>Barcode / SKU</th>
                <th className="numeric">Current Price</th>
                <th className="numeric">New Price</th>
                <th className="numeric">Difference</th>
                <th className="numeric">Change %</th>
                <th className="numeric">Lowest 30 Days</th>
                <th>Validity</th>
              </tr>
            </thead>

            <tbody>
              {items.map((item, index) => {
                const difference =
                  Number(item.newPrice || 0) - Number(item.oldPrice || 0);

                const direction =
                  difference < 0
                    ? "decreased"
                    : difference > 0
                      ? "increased"
                      : "";

                return (
                  <tr key={item.priceChangeItemId || index}>
                    <td>{index + 1}</td>

                    <td>
                      <strong>{text(item.productName)}</strong>
                      <small>{text(item.productCode)}</small>
                    </td>

                    <td>
                      <span>{text(item.barcode)}</span>
                      <small>{text(item.sku)}</small>
                    </td>

                    <td className="numeric">
                      {money(item.oldPrice, item.currencyCode)}
                    </td>

                    <td className={`numeric price ${direction}`}>
                      {money(item.newPrice, item.currencyCode)}
                    </td>

                    <td className={`numeric ${direction}`}>
                      {money(difference, item.currencyCode)}
                    </td>

                    <td className={`numeric ${direction}`}>
                      {number(item.changePercent)}%
                    </td>

                    <td className="numeric">
                      {money(item.lowestPrice30Days, item.currencyCode)}
                    </td>

                    <td>
                      {isPromotion ? (
                        <>
                          <strong>Until {date(item.promotionEndDate)}</strong>
                          <small>
                            Restore: {money(
                              item.restorePrice,
                              item.currencyCode
                            )}
                          </small>
                        </>
                      ) : (
                        <strong>Permanent</strong>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </section>

        {(header.reason || header.note) && (
          <section className="notes">
            {header.reason && (
              <div>
                <label>Reason</label>
                <p>{header.reason}</p>
              </div>
            )}

            {header.note && (
              <div>
                <label>Note</label>
                <p>{header.note}</p>
              </div>
            )}
          </section>
        )}

        <section className="approval">
          <div>
            <span>Prepared By</span>
            <strong>{text(header.createdBy)}</strong>
            <div className="signature"></div>
          </div>

          <div>
            <span>Approved By</span>
            <strong>{text(header.approvedBy)}</strong>
            <div className="signature"></div>
          </div>

          <div>
            <span>Posted By</span>
            <strong>{text(header.postedBy)}</strong>
            <div className="signature"></div>
          </div>

          <div className="barcode">
            <Barcode value={header.recordNumber} />
          </div>
        </section>

        <footer>
          <span>
            Printed: {text(model.printedAt)} by {text(model.printedBy)}
          </span>

          <span>
            This document provides an audit trail of product price changes.
          </span>
        </footer>
      </main>
    </div>
  );
}

let root;

function render() {
  if (!root) {
    root = createRoot(document.getElementById("root"));
  }

  root.render(<App />);
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
